#!/bin/bash

# Get WSL IP address
WSL_IP=$(ip addr show eth0 | grep -oP '(?<=inet\s)\d+(\.\d+){3}')

# Create local config override for the WSL IP
cat > _config_local.yml <<EOF
# Local development config - auto-generated by run_site.sh
url: "http://${WSL_IP}:4000"
EOF

echo "============================================"
echo "Starting Jekyll server..."
echo "Access from Windows browser at:"
echo "  http://${WSL_IP}:4000"
echo "  http://localhost:4000 (may work)"
echo "============================================"
echo ""

# Run Jekyll server bound to all interfaces with the WSL IP
# Override the url config to use the WSL IP for proper asset/image loading
sudo bundle exec jekyll serve -l -H ${WSL_IP} --config _config.yml,_config_local.yml
